# Extra category data for build-category-library.py.
# Each list is "Name|Name|..." with one icon. Patterns expand some lists (e.g. sports -> "Kids' soccer").
# Order matters: earlier entries rank higher in suggestions.

def split(s):
    return [x.strip() for x in s.split("|") if x.strip()]

def lc(name):
    """Lower-case the first letter unless it's a proper noun/acronym (keeps 'BMX', 'Ultimate frisbee' style)."""
    return name if (name.isupper() or name.split()[0] in PROPER) else name[0].lower() + name[1:]

PROPER = {"BMX", "CrossFit", "Zumba", "Pilates", "Frisbee", "Lego", "Little", "Pop", "Jiu-jitsu"}

