TEAM = {"Soccer","Baseball","Softball","Basketball","Football","Flag football","Volleyball","Hockey","Ice hockey","Field hockey","Lacrosse",
        "Water polo","Rugby","Cricket","Cheer","Dance team","Ultimate frisbee","Rowing","Crew","Handball","Netball","Kickball","Dodgeball"}
KIDS = TEAM | {"Swimming","Gymnastics","Karate","Taekwondo","Tennis","Golf","Track and field","Cross country","Wrestling","Skiing",
               "Snowboarding","Figure skating","Cycling","BMX","Skateboarding","Rock climbing","Horseback riding","Archery","Bowling",
               "Diving","Judo","Fencing","Pickleball","Boxing","Trampoline","Roller skating","Jiu-jitsu","Chess club","Esports"}
SCHOOL_LEVEL = {"Soccer","Baseball","Softball","Basketball","Football","Volleyball","Hockey","Lacrosse","Tennis","Golf","Swimming",
                "Track and field","Cross country","Wrestling","Cheer","Water polo","Field hockey","Rowing","Gymnastics","Dance team"}

def sports():
    out = []
    for s, ic in SPORTS:
        l = lc(s)
        out.append((s, ic))
        if s in KIDS: out.append((f"Kids' {l}", ic))
        if s in TEAM or s in {"Swimming","Gymnastics","Tennis","Golf","Wrestling","Track and field","Cross country","Skiing","Figure skating","Bowling","Karate"}:
            out += [(f"{s} games" if s in TEAM else f"{s} meets" if s in {"Swimming","Track and field","Cross country","Gymnastics","Diving"} else f"{s} competitions", ic),
                    (f"{s} practice", ic), (f"{s} team", ic), (f"{s} season", ic)]
        if s in TEAM or s in {"Tennis","Golf","Pickleball","Chess club","Esports","Bowling","Wrestling"}:
            out.append((f"{s} tournament", "trophy"))
        if s in SCHOOL_LEVEL:
            out += [(f"High school {l}", ic), (f"College {l}", ic), (f"Middle school {l}", ic)]
        if s in {"Soccer","Basketball","Baseball","Football","Hockey","Volleyball","Lacrosse","Softball"}:
            out += [(f"{s} camp", "tent"), (f"Travel {l}", ic), (f"Rec {l}", ic)]
    out += [(x, "ball") for x in split("Kids' sports|Youth sports|Little league|Pee wee football|Travel team|Club team|Rec league|Varsity|Junior varsity|Intramurals|Sports banquet|Senior night|Team photos|Sports pictures|Game day|Opening day|Playoffs|Championship game|Sports camp|Swim lessons|Swim team|All-stars|Coach|Coaching|Team mom|Team parents|Sideline|Bleachers|Scoreboard|Mascots|Pro games|Ballpark|Spring training|Super Bowl party|World Series|March Madness|Olympics|World Cup|Fantasy football|Marathon training|Half marathon|10K|Fun run|Color run|Turkey trot|Obstacle course race|Tough Mudder|Spartan race|Ironman")]
    return out

