def places():
    out = []
    out += [(c, "plane") for c in COUNTRIES]
    out += [(f"{c} trip", "plane") for c in COUNTRIES[:120] if not c.endswith(")")]
    out += [(s, "map") for s in STATES]
    out += [(c, "city") for c in CITIES]
    out += [(f"{c} trip", "city") for c in CITIES[:90] if "(" not in c]
    out += [(p, "mountain") for p in PARKS]
    out += [(l, "places") for l in LANDMARKS]
    return out

